styles:
/* Вход — кнопкой справа в верхней строке (toolbar, TOP_RIGHT; на телефоне — «☰ → Данные»):
   «Войти» или имя вошедшего; значок + подпись, как соседние кнопки строки */
.siteAccountButton {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  white-space: nowrap;
}
.siteAccountButton[hidden] {
  display: none;
}
.siteAccountButton .uiIcon {
  flex: none;
  width: 18px;
  height: 18px;
}
.siteAccountButton .uiLabel {
  overflow: hidden;
  text-overflow: ellipsis;
}
/* длинное имя не растягивает строку */
#toolbar .siteAccountButton .uiLabel {
  max-width: 140px;
}

/* Окна входа и «Вы вошли» — как окна правок клиента */
.siteDialog {
  max-width: 380px;
  width: calc(100vw - 32px);
  box-sizing: border-box;
  border: 1px solid #6c8696;
  border-radius: 8px;
  background: #101a21;
  color: #e9f1f4;
  padding: 16px 18px;
}
.siteDialog::backdrop {
  background: #03080c99;
}
.siteDialog h3 {
  margin: 0 0 6px;
  font-size: 15px;
}
.siteDialog p {
  margin: 0 0 8px;
  font-size: 13px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}
.siteDialog .siteHint {
  font-size: 12px;
  color: #a9bcc6;
}
.siteWho span {
  color: #a9bcc6;
}
/* «Как вас подписывать»: подпись над полем, поле — по ширине окна */
.siteNameBlock[hidden] {
  display: none;
}
.siteField {
  display: grid;
  gap: 3px;
  margin-bottom: 4px;
  font-size: 13px;
}
.siteField input {
  width: 100%;
  box-sizing: border-box;
}
/* «Доступ к чертежам» (владелец): список почт — строка «почта + Убрать», длинный — с
   прокруткой внутри; поле, под ним «Дать доступ» — компактно, по содержимому (Д-78) */
.siteAccess[hidden] {
  display: none;
}
.siteAccess {
  margin: 4px 0 10px;
  padding-top: 8px;
  border-top: 1px solid #2b3b46;
}
.siteAccess h4 {
  margin: 0 0 4px;
  font-size: 13px;
}
.siteAccessList {
  list-style: none;
  margin: 0 0 6px;
  padding: 0;
  max-height: 168px;
  overflow-y: auto;
}
.siteAccessList:empty {
  display: none;
}
.siteAccessList li {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 28px;
  font-size: 13px;
}
.siteAccessList li span {
  flex: 1 1 auto;
  min-width: 0;
  overflow-wrap: anywhere;
}
.siteAccessList button {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
}
.siteAccessList button svg {
  width: 16px;
  height: 16px;
}
.siteAccessAdd {
  margin-bottom: 4px;
}
@media (pointer: coarse) {
  .siteAccessList button {
    width: 44px;
    height: 44px;
  }
}
.siteGoogleButton {
  display: flex;
  min-height: 0;
  margin: 4px 0 8px;
}
.siteGoogleButton:empty {
  display: none;
}
.siteStatus:empty {
  display: none;
}
/* перенос настроек браузера — своей строкой над кнопками окна */
.siteImport {
  margin-bottom: 8px;
}
.siteImport[hidden] {
  display: none;
}
.siteButtons {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}
.siteDanger {
  margin-right: auto;
  border-color: #b06a5e;
  color: #ffc4ba;
}

