/* ── Токены оболочки (RF-013, дизайн-система RF-005 4.1). Имена --ui-*; прежние
   --panel, --muted, --accent шаблона остаются как есть. Цели касания — 44 px при
   сенсорном указателе, 32 px при мыши. ── */
:root {
  --ui-surface: rgb(23 35 45 / 0.95);
  --ui-surface-solid: #17232d;
  --ui-raised: #21313e;
  --ui-fill: #2c3d47;
  --ui-separator: #31414b;
  --ui-text: #e8eef0;
  --ui-text-secondary: #a6bac4;
  --ui-text-tertiary: #7f97a5;
  --ui-accent: #9ee2d0;
  --ui-accent-fill: #315e5d;
  --ui-on-accent: #caffed;
  --ui-warning: #e2b93b;
  --ui-info: #7ddcff;
  --ui-radius-s: 10px;
  --ui-radius-m: 14px;
  --ui-radius-l: 20px;
  /* Inter встроен в страницу модулем ui_font (RF-055); без него — системный шрифт */
  --ui-font: 'Inter', -apple-system, system-ui, 'Segoe UI', sans-serif;
  --ui-hit: 32px;
  --ui-bar: 34px; /* высота элементов верхней строки */
  --shell-left: 298px; /* левый край оболочки: справа от дерева */
  --shell-top: 64px; /* под верхней строкой; точное значение ставит adapter.js */
  --rail-w: 80px;
  --panel-max: 296px; /* П-5, П-22: панель по содержимому, не шире */
  /* Шкала слоёв (П-23): левое меню, панель, блоки и плавающие окна, раскрытые меню.
     Раскрытое меню и «☰» — выше любого окна и блока. */
  --z-rail: 20;
  --z-panel: 21;
  --z-block: 22;
  --z-window: 23;
  --z-window-top: 24;
  --z-menu: 200;
  --z-popup: 210;
}
@media (pointer: coarse) {
  :root {
    --ui-hit: 44px;
    --ui-bar: 44px;
  }
}
@media (max-width: 760px) {
  :root {
    --shell-left: 8px;
    --rail-w: 66px;
    --ui-bar: 44px;
  }
}
@media (min-width: 761px) {
  html.sideCollapsed {
    --shell-left: 12px;
  }
  html.sideCollapsed .side {
    display: none;
  }
  html.sideCollapsed #viewport {
    left: 0;
  }
  html.sideCollapsed .footer {
    left: 104px;
  }
}

/* ── Верхняя строка: ☰ · режимы и выбор · (пусто) · дискета, «Обновить»,
   «Демонстрация», клавиши. Одна строка на любой ширине. ── */
#toolbar.top {
  left: var(--shell-left);
  right: 12px;
  top: 12px;
  width: auto;
  max-width: none;
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
  padding: 0;
  background: none;
  border: 0;
  border-radius: 0;
  z-index: 23;
}
/* «☰» раскрыт — верхняя строка с его списком выше окон и блоков (П-23). Строка —
   position: fixed, то есть свой слой: список внутри неё выше её самой не встанет */
#toolbar.top:has(#viewerMenuToggle[aria-expanded='true']) {
  z-index: var(--z-menu);
}
#toolbar.top::after {
  content: '';
  order: 5;
  flex: 1 1 0;
  min-width: 0;
}
#toolbar > * {
  flex: none;
}
#toolbar button {
  font-size: 13px;
}
#viewerMenu {
  order: 0;
  position: relative;
  flex: none;
}
.viewerMenuToggle {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: var(--ui-bar);
  height: var(--ui-bar);
  padding: 0;
  font-size: 18px;
  line-height: 1;
  border-radius: var(--ui-radius-s);
  background: var(--ui-surface);
  border-color: var(--ui-separator);
}
.viewerMenuToggle > .uiIcon,
#closeStructure > .uiIcon {
  width: 20px;
  height: 20px;
}
#viewerMenuToggle[aria-expanded='true'] {
  background: var(--ui-accent-fill);
  border-color: var(--ui-accent);
  color: var(--ui-on-accent);
}
#toolbar #displayPanel {
  order: 1;
  flex: 0 1 auto;
  min-width: 0;
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 8px;
  padding: 3px;
  max-width: none;
  overflow: visible;
  background: var(--ui-surface);
  border: 1px solid var(--ui-separator);
  border-radius: 12px;
}
#toolbar #displayPanel > .displayModes {
  order: 0;
}
#toolbar #selectionTools {
  order: 1;
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 6px;
  flex: none;
}
#toolbar #selectionTools > *,
#toolbar #displayPanel .visibilityTools {
  flex: none;
  display: flex;
  gap: 6px;
}
#toolbar #selectionTools button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: var(--ui-bar);
  min-width: var(--ui-bar);
  padding: 0 10px;
  white-space: nowrap;
  border-radius: var(--ui-radius-s);
  background: var(--ui-raised);
  border-color: var(--ui-separator);
}
#toolbar #selectionTools button:hover:not(:disabled, [aria-disabled='true']) {
  background: var(--hover);
}
/* «Выбор: объект / сборка» — выбор из двух, а не включённая кнопка */
#toolbar #visibilityMode[aria-pressed] {
  background: var(--ui-raised);
  border-color: var(--ui-separator);
  color: var(--ui-text);
}
#toolbar :is(#panelHardwareToggle, #facadesToggle, #openingDoors, #openingDrawers)[aria-pressed='true'] {
  background: var(--ui-accent-fill);
  border-color: var(--ui-accent);
  color: var(--ui-on-accent);
}
#toolbar #selectionTools button:is(:disabled, [aria-disabled='true']) {
  opacity: 1;
  color: var(--ui-text-tertiary);
  background: var(--ui-fill);
  border-color: transparent;
}
/* П-11: линейка замера — значком в верхней строке, после выбора и видимости; имя —
   в подсказке и aria-label (текст кнопки меняет шаблон: «Завершить замер») */
#toolbar #selectionTools > #visibilityTools {
  order: 0;
}
#toolbar #selectionTools > #measure {
  order: 1;
}
#toolbar #selectionTools > #panelHardwareToggle {
  order: 2;
}
/* «Фасады» (RF-028, Д-85): значок двери — рисунок в разметке, подпись убираемая */
#toolbar #selectionTools > #facadesToggle {
  order: 3;
}
/* «Открыть двери», «Выдвинуть ящики» (RF-051, П-39) — сразу за «Фасадами», так же */
#toolbar #selectionTools > :is(#openingDoors, #openingDrawers) {
  order: 4;
}
@media (min-width: 761px) {
  #toolbar #selectionTools #measure {
    font-size: 0;
    gap: 0;
    padding: 0;
    width: var(--ui-bar);
  }
}
#toolbar #selectionTools #measure[aria-pressed='true'] {
  background: var(--ui-accent-fill);
  border-color: var(--ui-accent);
  color: var(--ui-on-accent);
}
/* справа: обновление, правки, дискета, демонстрация, клавиши */
#toolbar > #viewerUpdate {
  order: 6;
}
#toolbar > #inboxLoad,
#toolbar > #inboxSend,
#toolbar > #inboxState {
  order: 7;
}
#toolbar > #githubSaveTools {
  order: 8;
  flex: none;
  padding: 0;
  border: 0;
  background: none;
}
/* язык и вход (TOP_RIGHT в adapter.js) — перед «Демонстрацией», тем же порядком в DOM */
#toolbar > :is(#langControl, #siteAccount, #guideOpen) {
  order: 9;
}
#toolbar > #siteAccount {
  height: var(--ui-bar);
  border-radius: var(--ui-radius-s);
  background: var(--ui-surface);
  border-color: var(--ui-separator);
}
#toolbar > #hotkeysMenu {
  order: 10;
}
#toolbar > :is(#viewerUpdate, #inboxLoad, #inboxSend, #guideOpen),
#saveGithub {
  height: var(--ui-bar);
  min-width: var(--ui-bar);
  border-radius: var(--ui-radius-s);
  background: var(--ui-surface);
  border-color: var(--ui-separator);
}
#saveGithub {
  width: var(--ui-bar);
  padding: 4px;
  display: grid;
  place-items: center;
}
/* Строке не хватает места (RF-031): ступени вместимости в adapter.js — по фактической
   ширине содержимого, не по брейкпоинту. Убираемые подписи прячутся по одной группе,
   кнопки сжимаются до значка: .topCompactGuide — «Демонстрация», .topCompact — кнопки
   выбора, .topCompactAll — имя входа. Не помогло — язык и вход, затем дискета, правки
   и «Обновить» уезжают в «☰». На телефоне строку раскладывает своё правило ниже. */
@media (min-width: 761px) {
  #toolbar.topCompact
    :is(#visibilityRestore, #panelHardwareToggle, #facadesToggle, #openingDoors, #openingDrawers) {
    font-size: 0;
    padding: 0;
    width: var(--ui-bar);
  }
  /* без модуля значков — короткая подпись; значки её прячут */
  #toolbar.topCompact :is(#visibilityRestore, #panelHardwareToggle)::after {
    content: attr(data-compact-label);
    font-size: 14px;
  }
  #toolbar.topCompactGuide #guideOpen .guideOpenLabel,
  #toolbar.topCompactAll > #siteAccount .uiLabel {
    display: none;
  }
}
@media (min-width: 761px) and (max-width: 1100px) {
  /* планшет с деревом слева: строке тесно (линейка П-11 добавила кнопку) — зазоры
     уже, «?» ряда (guide) — как на телефоне, справка через «Демонстрацию» */
  #toolbar #displayPanel,
  #toolbar #selectionTools,
  #toolbar #selectionTools > *,
  #toolbar #displayPanel .visibilityTools {
    gap: 4px;
  }
  #toolbar #displayPanel > .guideQ {
    display: none;
  }
  #toolbar #selectionTools #visibilityMode {
    font-size: 0;
    padding: 0 8px;
  }
  #toolbar #selectionTools #visibilityMode::after {
    content: attr(data-compact-label);
    font-size: 13px;
  }
}

/* ── Меню инструментов слева ── */
#functionalModules.toolRail {
  position: fixed;
  z-index: 20;
  left: var(--shell-left);
  top: var(--shell-top);
  width: var(--rail-w);
  /* не заходит на кнопку и ленту «Фурнитура» (--hardwareBarH) и лист (--sheet-h):
     на низком экране с открытым листом меню прокручивается само */
  max-height: calc(
    100vh - var(--shell-top) - max(64px, var(--sheet-h, 0px) + var(--hardwareBarH, 8px) + 16px)
  );
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 4px 0; /* кнопки во всю ширину столбца, как строки бокового меню iOS */
  overflow-x: hidden;
  overflow-y: auto;
  scrollbar-width: none;
  background: var(--ui-surface);
  border: 1px solid var(--ui-separator);
  border-radius: var(--ui-radius-m);
}
.toolRail > button {
  position: relative;
  flex: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  width: 100%;
  min-height: 56px;
  padding: 6px 2px;
  border: 0;
  border-radius: var(--ui-radius-s);
  background-color: transparent;
  color: var(--ui-text-secondary);
  font-size: 11px;
  line-height: 13px;
  text-align: center;
  white-space: nowrap;
}
.toolRail > button:hover {
  background-color: var(--ui-fill);
  color: var(--ui-text);
}
.toolRail > button[aria-expanded='true'] {
  background-color: var(--ui-accent-fill);
  color: var(--ui-on-accent);
}
/* «Структура» — не инструмент, а переключатель дерева (решение владельца 25.10.2026):
   отделена чертой, не заливается как открытый инструмент; пока дерево видно,
   горит её значок и полоска слева. Так в меню подсвечен только открытый инструмент. */
.toolRail > #mobileStructure {
  margin-top: 4px;
  box-shadow: 0 -5px 0 -4px var(--ui-separator);
}
.toolRail > #mobileStructure[aria-expanded='true'] {
  background-color: transparent;
  color: var(--ui-accent);
  box-shadow:
    0 -5px 0 -4px var(--ui-separator),
    inset 3px 0 0 var(--ui-accent);
}
.toolRail > #mobileStructure[aria-expanded='true']:hover {
  background-color: var(--ui-fill);
}
.toolRail > button[hidden] {
  display: none;
}
/* Режим включён, а его панель спрятана — точка в углу (цвет модуля) */
.toolRail > button.toolSuspended {
  background-image: radial-gradient(circle at 9px 9px, var(--ui-info) 3.5px, transparent 4.5px);
}
#functionalModules.toolRail {
  z-index: var(--z-rail);
}
.toolRail > #notesOpen.toolSuspended {
  background-image: radial-gradient(circle at 9px 9px, var(--ui-warning) 3.5px, transparent 4.5px);
}
@media (max-width: 760px) {
  .toolRail > button {
    min-height: 52px;
    padding: 5px 0;
    font-size: 10px; /* «Отображение» (П-12) — во всю подпись в столбце 66 px */
    letter-spacing: -0.4px; /* Inter шире системного (RF-055): -0,2 px давало 66,5 px в 66 */
  }
}

/* ── Панель инструмента: ПК — рядом с меню слева, телефон — лист снизу ── */
/* Автораскладка (П-5, П-22, П-28): панель — по содержимому («обтянуть»), не шире
   --panel-max; кнопки растягиваются только до самой широкой соседки в столбце;
   пояснения и строки состояния переносятся по ширине кнопок и ширину не задают. */
.toolPanel {
  position: fixed;
  z-index: var(--z-panel);
  left: calc(var(--shell-left) + var(--rail-w) + 8px);
  top: var(--shell-top);
  width: max-content;
  min-width: 0;
  max-width: min(var(--panel-max), calc(100vw - var(--shell-left) - var(--rail-w) - 20px));
  max-height: calc(100vh - var(--shell-top) - 64px);
  display: flex;
  flex-direction: column;
  background: var(--ui-surface-solid);
  border: 1px solid var(--ui-separator);
  border-radius: var(--ui-radius-m);
  box-shadow: 0 12px 35px #0008;
  font-size: 13px;
}
.toolPanel[hidden] {
  display: none;
}
/* шапка: [название][?][×] друг за другом, без зарезервированного места (П-28) */
.toolPanelHead {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 6px;
  padding: 8px 8px 0 14px;
}
.toolPanelHead h2 {
  flex: 0 1 auto;
  min-width: 0;
  margin: 0 4px 0 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
  color: var(--ui-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.toolPanelClose {
  flex: none;
  display: grid;
  place-items: center;
  width: var(--ui-hit);
  height: var(--ui-hit);
  padding: 0;
  font-size: 20px;
  line-height: 1;
  border-radius: var(--ui-radius-s);
}
.toolPanelClose > .uiIcon {
  width: 18px;
  height: 18px;
}
.toolPanelBody {
  min-height: 0;
  overflow: auto;
  padding: 8px 14px 14px;
  scrollbar-width: thin;
}
.toolPanelBody > .featureRow {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 0;
  margin: 0;
  max-height: none;
  overflow: visible;
  background: none;
  border: 0;
  font-size: 13px;
}
.featureRow[hidden] {
  display: none !important;
}
.featureRow .tools {
  align-items: center;
}
.featureRow button {
  padding: 6px 10px;
  min-height: var(--ui-hit);
}
.featureRow .check {
  padding: 2px 0;
  min-height: var(--ui-hit);
}
/* ── Телефон: лист снизу не выше 40 % экрана (замечание владельца после пробы на
   S24), содержимое прокручивается внутри. Заголовок и × — одной строкой 44 px. ── */
@media (max-width: 760px) {
  .toolPanel {
    left: 0;
    right: 0;
    top: auto;
    bottom: 0;
    width: auto;
    max-width: none;
    max-height: 40vh;
    max-height: 40dvh;
    border-bottom: 0;
    border-radius: var(--ui-radius-l) var(--ui-radius-l) 0 0;
    box-shadow: 0 -10px 30px #0009;
    padding-bottom: env(safe-area-inset-bottom, 0px);
  }
  .toolPanelHead {
    position: relative;
    flex: none;
    padding: 12px 6px 0 16px;
  }
  .toolPanelHead::before {
    content: '';
    position: absolute;
    left: 50%;
    top: 5px;
    width: 36px;
    height: 5px;
    margin-left: -18px;
    border-radius: 3px;
    background: var(--ui-separator);
  }
  .toolPanelHead h2 {
    font-size: 17px;
    line-height: 22px;
  }
  /* × — круг 30 px внутри цели 44 px, как у листов iOS */
  .toolPanelClose {
    width: 44px;
    height: 44px;
    border: 0;
    background: radial-gradient(circle, var(--ui-fill) 15px, transparent 16px);
    color: var(--ui-text-secondary);
    font-size: 20px;
  }
  .toolPanelClose:hover,
  .toolPanelClose:focus-visible {
    background: radial-gradient(circle, var(--ui-separator) 15px, transparent 16px);
    color: var(--ui-text);
  }
  .toolPanelBody {
    padding: 6px 16px 16px;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
  }
}

/* ── Панель инструмента (ПК) и лист (телефон): правило владельца 24.10.2026 —
   ОДИН ЭЛЕМЕНТ — ОДНА СТРОКА. В ряд встают только однотипные элементы — сегмент
   (.toolSegment; у шаблона тот же смысл у .views: «Текстура · Кромки · Монотон»,
   как режимы отображения). Строка инструмента (.featureRow) и обёртки модулей с
   классом .toolStack — столбец; кнопка, меню, флажок, поле выбора и ползунок с
   подписью — во всю ширину, одной высоты (цель касания --ui-hit: 44 px на
   сенсорном экране), между строками 8 px. «?» подсказки — в заголовке панели,
   справа от названия. Модули ставят свои элементы как раньше и помечают обёртки
   классом .toolStack; вид — здесь. ── */
.toolPanelBody > .featureRow,
.toolPanelBody .toolStack {
  display: flex;
  flex-direction: column;
  flex-wrap: nowrap;
  align-items: stretch;
  gap: 8px;
  min-width: 0;
}
.toolPanelBody .toolStack {
  flex: none;
  width: 100%;
  margin: 0;
  padding: 0;
}
.toolPanelBody :is(.featureRow, .toolStack) > *:not(.compactHelp) {
  margin: 0;
  min-width: 0;
}
/* однотипные — в ряд, поровну; сегмент — общий элемент, тот же и в плавающем окне.
   Вид — компактная «капсула», как режимы отображения в верхней строке (Д-78, без больших
   кнопок): общий фон, варианты без своих рамок, выбранный приподнят и подсвечен. */
:is(.toolPanelBody, .floatWinBody) :is(.toolSegment, .views) {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  gap: 2px;
  width: 100%;
  padding: 2px;
  border-radius: 10px;
  background: var(--ui-fill);
}
:is(.toolPanelBody, .floatWinBody) :is(.toolSegment, .views) > * {
  flex: 1 1 0;
  min-width: 0;
}
/* строка: кнопка, меню, флажок, выбор — во всю ширину, текст слева */
.toolPanelBody :is(.featureRow, .toolStack) > :is(button, select, label.check),
.toolPanelBody :is(.featureRow, .toolStack) > span > button,
.toolPanelBody :is(.featureRow, .toolStack) > .toolMenu > summary,
.toolPanelBody :is(.featureRow, .toolStack) > label:has(> select) {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  width: 100%;
  min-height: var(--ui-hit);
  padding: 0 12px;
  border: 1px solid var(--ui-separator);
  border-radius: var(--ui-radius-s);
  background: var(--ui-raised);
  color: var(--ui-text);
  font-size: 13px;
  text-align: left;
  white-space: normal;
}
.toolPanelBody :is(.featureRow, .toolStack) > span:has(> button),
.toolPanelBody :is(.featureRow, .toolStack) > .toolMenu,
.toolPanelBody :is(.featureRow, .toolStack) > label:has(> select) {
  display: flex;
  width: 100%;
}
.toolPanelBody :is(.featureRow, .toolStack) > :is(label.check, label):has(> select) {
  padding: 0;
  border: 0;
  background: none;
}
.toolPanelBody :is(.featureRow, .toolStack) > label:has(> select) > select {
  flex: 1;
  min-height: var(--ui-hit);
  border-radius: var(--ui-radius-s);
}
.toolPanelBody :is(.featureRow, .toolStack) > button:disabled {
  color: var(--ui-text-tertiary);
  background: var(--ui-fill);
  border-color: transparent;
  opacity: 1;
}
.toolPanelBody :is(.featureRow, .toolStack) > button[aria-pressed='true'],
.toolPanelBody :is(.featureRow, .toolStack) > span > button[aria-pressed='true'],
.toolPanelBody :is(.featureRow, .toolStack) > .toolMenu[open] > summary {
  border-color: var(--ui-accent);
  background: var(--ui-accent-fill);
  color: var(--ui-on-accent);
}
:is(.toolPanelBody, .floatWinBody) :is(.toolSegment, .views) > button {
  justify-content: center;
  min-height: 28px;
  padding: 0 6px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--ui-text-secondary);
  font-size: 12px;
}
:is(.toolPanelBody, .floatWinBody) :is(.toolSegment, .views) > button:hover {
  background: var(--hover);
  color: var(--ui-text);
}
:is(.toolPanelBody, .floatWinBody) :is(.toolSegment, .views) > button[aria-pressed='true'] {
  border-color: var(--ui-separator);
  background: var(--ui-raised);
  color: var(--ui-text);
  box-shadow: 0 1px 3px #0008;
}
:is(.toolPanelBody, .floatWinBody) :is(.toolSegment, .views) > button[aria-pressed='true'] > .uiIcon {
  color: var(--ui-accent);
}
/* телефон (сенсорный экран или лист снизу): цель касания 44 px остаётся (ui-rules, п. 3) */
@media (pointer: coarse), (max-width: 760px) {
  :is(.toolPanelBody, .floatWinBody) :is(.toolSegment, .views) > button {
    min-height: 44px;
  }
}
/* меню-строка: стрелка справа — откроется окно */
.toolPanelBody :is(.featureRow, .toolStack) > .toolMenu > summary {
  list-style: none;
  cursor: pointer;
}
.toolPanelBody :is(.featureRow, .toolStack) > .toolMenu > summary::-webkit-details-marker {
  display: none;
}
.toolPanelBody :is(.featureRow, .toolStack) > .toolMenu > summary::after {
  content: '›';
  margin-left: auto;
  color: var(--ui-text-tertiary);
  font-size: 18px;
}
/* флажок: квадрат, подпись, число справа */
.toolPanelBody :is(.featureRow, .toolStack) > label.check {
  background: var(--ui-surface-solid);
}
.toolPanelBody :is(.featureRow, .toolStack) > label.check input {
  flex: none;
  width: 18px;
  height: 18px;
  margin: 0;
}
.toolPanelBody :is(.featureRow, .toolStack) > label.check small {
  margin-left: auto;
  min-width: 20px;
  padding: 1px 6px;
  border-radius: 9px;
  background: var(--ui-fill);
  color: var(--ui-text-secondary);
  font-size: 11px;
  line-height: 16px;
  text-align: center;
  font-variant-numeric: tabular-nums;
}
/* Ползунок (П-8; ui-rules, п. 2): строкой — значок, подпись, значение; ползунок —
   под ними во всю ширину. Вид ползунка — общий input[type=range] шаблона. Так и в
   панели, и во всплывающих окнах, и в плавающих: прокрутки вбок нет. */
:is(.toolPanelBody, .toolPopupPortal, .floatWinBody) :is(label, .opacityTool):has(> input[type='range']) {
  display: grid !important;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 2px 8px;
  width: 100%;
  min-width: 0;
  min-height: 0;
  padding: 2px 2px 0;
  white-space: normal;
}
:is(.toolPanelBody, .toolPopupPortal, .floatWinBody)
  :is(label, .opacityTool):has(> input[type='range'])
  > input[type='range'] {
  grid-column: 1 / -1;
  grid-row: 2;
  width: 100% !important;
  min-width: 0;
  max-width: none;
  margin: 6px 0 8px;
}
:is(.toolPanelBody, .toolPopupPortal, .floatWinBody)
  :is(label, .opacityTool):has(> input[type='range'])
  > :is(output, span:last-child:not(:first-child)) {
  grid-column: 3;
  grid-row: 1;
  width: auto;
  min-width: 0;
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: var(--ui-text-secondary);
}
/* без значка подпись — в первой колонке; значение всё равно справа */
:is(.toolPanelBody, .toolPopupPortal, .floatWinBody)
  :is(label, .opacityTool):has(> input[type='range'])
  > :is(label, span:not(:last-child), .uiLabel) {
  min-width: 0;
}
/* пояснение модуля — обычным абзацем под строками */
.toolPanelBody :is(.featureRow, .toolStack) > :is(.noteStatus, .subtle, small) {
  max-width: none;
  color: var(--ui-text-secondary);
  font-size: 12px;
}
/* П-28: пояснения, подсказки и строки состояния переносятся по ширине кнопок и сами
   ширину панели не задают (нулевая собственная ширина — contain: inline-size) */
.toolPanelBody
  :is(
    p,
    .subtle,
    .hint,
    .notice,
    [role='status'],
    [aria-live],
    [id$='Status'],
    [id$='Hint'],
    .noteStatus,
    .notesHint
  ),
.toolPanelBody :is(.featureRow, .toolStack) > small,
.floatWinBody :is(p, .subtle, .hint, .notice, [role='status'], [aria-live], [id$='Status'], [id$='Hint']) {
  contain: inline-size;
  overflow-wrap: anywhere;
}
/* подсказка строки в теле не видна: её «?» стоит в шапке (adapter.js переносит) */
.toolPanelBody .compactHelp {
  display: none;
}
/* «?» в шапке — между названием и ×, значок общего набора (маска --ui-icon-help) */
.toolPanelHelp {
  display: contents;
}
.toolPanelHelp > .compactHelp {
  position: relative;
  flex: none;
  margin: 0;
}
.toolPanelHelp > .compactHelp > summary {
  display: grid;
  place-items: center;
  width: var(--ui-hit);
  height: var(--ui-hit);
  padding: 0;
  border: 0;
  border-radius: var(--ui-radius-s);
  background: transparent;
  color: var(--ui-text-secondary);
  font-size: 0;
  list-style: none;
  cursor: pointer;
}
.toolPanelHelp > .compactHelp > summary::before {
  content: '';
  width: 20px;
  height: 20px;
  background: currentColor;
  mask: var(--ui-icon-help) center / contain no-repeat;
  -webkit-mask: var(--ui-icon-help) center / contain no-repeat;
}
.toolPanelHelp > .compactHelp > summary::-webkit-details-marker {
  display: none;
}
.toolPanelHelp > .compactHelp > summary:hover {
  background: var(--ui-fill);
  color: var(--ui-text);
}
.toolPanelHelp > .compactHelp[open] > summary {
  background: var(--ui-accent-fill);
  color: var(--ui-on-accent);
}
/* окно подсказки — в общем слое справа от панели (portalToolMenu) */
.compactHelpBody.toolPopupPortal {
  padding: 10px 12px;
  color: var(--ui-text-secondary);
  font-size: 12px;
  line-height: 1.4;
}
.compactHelpBody.toolPopupPortal > * {
  margin: 0 0 8px;
}
.compactHelpBody.toolPopupPortal > :last-child {
  margin-bottom: 0;
}

/* ── «☰»: сгруппированный список ── */
#viewerMenuPopup[hidden] {
  display: none !important;
}
#viewerMenu > #viewerMenuPopup {
  position: fixed;
  left: var(--shell-left);
  top: var(--shell-top);
  right: auto;
  width: 340px;
  max-width: calc(100vw - 24px);
  max-height: calc(100vh - var(--shell-top) - 12px);
  overflow: auto;
  z-index: 30;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 12px 14px;
  background: var(--ui-surface-solid);
  border: 1px solid var(--ui-separator);
  border-radius: var(--ui-radius-m);
  box-shadow: 0 14px 40px #000b;
}
#viewerMenuPopup .menuHead {
  margin: 10px 4px 4px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ui-text-tertiary);
}
#viewerMenuPopup .menuGroup {
  flex-direction: column;
  align-items: stretch;
  background: var(--ui-surface-solid);
  border: 1px solid var(--ui-separator);
  border-radius: 12px;
  overflow: hidden;
}
/* пустая группа (у локального файла нет статистики, у клиента — дискеты) не видна */
#viewerMenuPopup .menuGroup,
#viewerMenuPopup .menuHead {
  display: none;
}
#viewerMenuPopup .menuGroup:has(> :not([hidden]):not(.hidden)) {
  display: flex;
}
#viewerMenuPopup .menuHead:has(+ .menuGroup > :not([hidden]):not(.hidden)) {
  display: block;
}
/* без #dev: «Вид» (служебное) и «Для разработчика» не показываются (02.11.2026) */
#viewerMenuPopup.menuNoDev :is([data-group='view'], #menuDev) {
  display: none !important;
}
/* без #dev в «☰» нечего показать (локальный файл: ни статистики, ни языка с входом на
   телефоне) — нет и кнопки «☰» */
#viewerMenu:has(> #viewerMenuPopup.menuNoDev):not(
    :has(.menuGroup:is([data-group='owner'], [data-group='language'], [data-group='data']) > :not([hidden], .hidden))
  ) {
  display: none;
}
/* у клиента дискеты нет (github_save прячет её стилем, не hidden) — пустой полосы сверху
   «☰» на телефоне тоже */
.bazisClient #viewerMenuPopup .menuGroup[data-group='owner']:not(:has(> :not([hidden], .hidden, #githubSaveTools))) {
  display: none;
}
/* «Предложить улучшение», галочка статистики и пояснение — столбцом, по одному в строке */
#viewerMenuPopup .menuGroup > #usageTools {
  flex-direction: column;
  align-items: stretch;
  gap: 6px;
  padding: 8px 12px;
}
#viewerMenuPopup #usageTools > .usageFeedback {
  align-self: flex-start;
}
#viewerMenuPopup .menuGroup[data-group='owner'] {
  margin-top: 4px;
}
/* строки одной высоты с разделителями: кнопки, флажки, ползунки, вложенные меню */
#viewerMenuPopup .menuGroup > *,
#viewerMenuPopup #featureExtras > * {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: var(--ui-hit);
  margin: 0;
  padding: 4px 12px;
  border: 0;
  border-top: 1px solid var(--ui-separator);
  border-radius: 0;
  background: transparent;
  width: 100%;
  text-align: left;
  color: var(--ui-text);
  font-size: 13px;
}
#viewerMenuPopup .menuGroup > :first-child {
  border-top: 0;
}
#viewerMenuPopup .menuGroup > [hidden],
#viewerMenuPopup .menuGroup > .hidden,
#viewerMenuPopup #featureExtras > [hidden],
#viewerMenuPopup #toggleSide {
  display: none !important;
}
#viewerMenuPopup #featureExtras {
  display: flex;
  flex-direction: column;
  padding: 0;
}
/* все пункты модулей переехали в «Отображение» (UI-001, часть I) — пустой строки нет.
   Не :empty: пробел или перевод строки от разметки оставил бы строку */
#viewerMenuPopup #featureExtras:not(:has(> :not([hidden], .hidden))) {
  display: none;
}
/* кнопки-переключатели модулей в «☰» — строками списка */
#viewerMenuPopup :is(.menuGroup, #featureExtras) > span > button,
#viewerMenuPopup :is(.menuGroup, #featureExtras) > button {
  justify-content: flex-start;
}
#viewerMenuPopup :is(.menuGroup, #featureExtras) > span > button {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  margin: -4px -12px;
  padding: 4px 12px;
  min-height: var(--ui-hit);
  border: 0;
  border-radius: 0;
  background: transparent;
  text-align: left;
}
#viewerMenuPopup :is(.menuGroup, #featureExtras) > button[aria-pressed='true'],
#viewerMenuPopup :is(.menuGroup, #featureExtras) > span > button[aria-pressed='true'] {
  background: transparent;
  color: var(--ui-accent);
}
#viewerMenuPopup :is(.menuGroup, #featureExtras) > button[aria-pressed='true']::after,
#viewerMenuPopup :is(.menuGroup, #featureExtras) > span > button[aria-pressed='true']::after {
  content: '✓';
  margin-left: auto;
}
#viewerMenuPopup :is(.menuGroup, #featureExtras) > .guideQ {
  min-height: 0;
  padding: 0 12px 4px;
  border-top: 0;
  justify-content: flex-end;
}
#viewerMenuPopup .menuGroup button:hover,
#viewerMenuPopup .menuGroup > .toolMenu > summary:hover {
  background: var(--hover);
}
#viewerMenuPopup .menuGroup > .toolMenu {
  display: block;
  padding: 0;
}
#viewerMenuPopup .menuGroup > .toolMenu > summary {
  display: flex;
  align-items: center;
  min-height: var(--ui-hit);
  padding: 4px 12px;
  font-size: 13px;
  color: var(--ui-text);
  border-radius: 0;
}
/* вложенные окна в «☰» раскрываются на месте, а не отдельным окном */
#viewerMenuPopup .toolMenu > .toolPopup:not(.toolPopupPortal) {
  position: static;
  width: auto;
  max-width: none;
  max-height: none;
  overflow: visible;
  margin: 0;
  padding: 0 12px 8px 22px;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  background: transparent;
}
#viewerMenuPopup .opacityTool .range,
#viewerMenuPopup .lineWidthTool .range {
  flex: 1 1 auto;
  width: auto;
  min-width: 80px;
  max-width: none;
}
#viewerMenuPopup :is(.opacityTool, .lineWidthTool) {
  white-space: normal;
}
#viewerMenuPopup .opacityTool > :last-child {
  width: 44px;
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: var(--ui-text-secondary);
}
#viewerMenuPopup .menuGroup .check input {
  width: 18px;
  height: 18px;
}
#viewerMenuPopup .subtle {
  font-size: 12px;
  color: var(--ui-text-secondary);
}
#viewerMenuPopup [role='status'] {
  position: static;
  background: none;
  max-width: none;
}
#viewerMenuPopup .menuGroup[data-group='owner'] > #githubSaveTools {
  flex-wrap: wrap;
}
/* «?» демонстрации — в конце ряда; в верхней строке телефона на него нет места */
#toolbar #displayPanel > .guideQ {
  order: 2;
  flex: none;
}
#viewerMenuPopup > .guideQ {
  align-self: flex-end;
  margin: 6px 4px 0;
}
@media (max-width: 760px) {
  #toolbar #displayPanel > .guideQ {
    display: none;
  }
}
#viewerMenuPopup .menuDev {
  margin-top: 10px;
}
#viewerMenuPopup .menuDev > summary {
  display: flex;
  align-items: center;
  min-height: var(--ui-hit);
  padding: 4px 12px;
  font-size: 13px;
  color: var(--ui-text-secondary);
  background: var(--ui-surface-solid);
  border: 1px solid var(--ui-separator);
  border-radius: 12px;
}
#viewerMenuPopup .menuDev[open] > summary {
  border-radius: 12px 12px 0 0;
}
#viewerMenuPopup .menuDev > .menuGroup {
  border-top: 0;
  border-radius: 0 0 12px 12px;
}
/* то же на ПК, когда строке тесно и правки с «Обновить» уехали в «☰» (RF-031) */
#toolbar.topCrowded
  #viewerMenu:has(
    :is(#viewerUpdate, #inboxSend, #inboxLoad, #inboxState:is([data-state='login'], [data-state='error'])):not(
        [hidden]
      )
  )
  #viewerMenuToggle::after {
  content: '';
  position: absolute;
  top: 6px;
  right: 6px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ui-info);
}
/* «Обновить» или пришедшие правки на телефоне — точка на «☰» */
@media (max-width: 760px) {
  #viewerMenu:has(
      :is(#viewerUpdate, #inboxSend, #inboxLoad, #inboxState:is([data-state='login'], [data-state='error'])):not(
          [hidden]
        )
    )
    #viewerMenuToggle::after {
    content: '';
    position: absolute;
    top: 6px;
    right: 6px;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--ui-info);
  }
  #viewerMenu > #viewerMenuPopup {
    left: 8px;
    right: 8px;
    width: auto;
    max-width: none;
  }
}

.compactHelp {
  position: relative;
}
.compactHelp > summary {
  list-style: none;
  border: 1px solid var(--popup-border);
  border-radius: 50%;
  width: 24px;
  height: 24px;
  text-align: center;
  cursor: pointer;
}
.compactHelp > div {
  position: fixed;
  z-index: 50;
  left: 12px;
  right: 12px;
  top: 120px;
  background: var(--panel);
  border: 1px solid var(--popup-border);
  padding: 10px;
  border-radius: 8px;
  max-height: 35vh;
  overflow: auto;
}
#viewerMenuPopup .compactHelp {
  padding: 0 12px 6px;
  min-height: 0;
  border-top: 0;
}
/* пояснение и строка состояния замера — в «?» раздела «Отображение» */
.compactHelpBody :is(.notice, .measureStatus) {
  min-height: 0;
  margin: 0 0 8px;
  padding: 0;
  border: 0;
  font-size: 12px;
  color: var(--ui-text-secondary);
}
/* Сборочные единицы: «Общий вид» (пока выбран узел) и кнопка текущего узла со
   списком — одной строкой справа под кубом. Список — в общем слое (portalToolMenu). */
.assemblyUnits {
  position: absolute;
  right: 8px;
  top: 148px; /* под видовым кубом: куб 48 + 96 */
  z-index: 4;
  display: flex;
  align-items: flex-start;
  gap: 5px;
  max-width: calc(100% - 16px);
}
.assemblyUnits[hidden] {
  display: none;
}
.assemblyUnits button,
.assemblyUnitsList button {
  text-align: left;
  font-size: 12px;
  padding: 6px 9px;
}
.assemblyUnits button[hidden] {
  display: none;
}
.assemblyUnitsMenu > summary {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 30px;
  padding: 5px 10px;
  border: 1px solid #415563;
  border-radius: 7px;
  background: #21313e;
  color: var(--text);
  font-size: 12px;
  font-weight: 600;
  list-style: none;
  cursor: pointer;
  white-space: nowrap;
}
.assemblyUnitsMenu > summary::-webkit-details-marker {
  display: none;
}
.assemblyUnitsMenu > summary::after {
  content: '▾';
  opacity: 0.7;
}
.assemblyUnitsMenu[open] > summary,
.assemblyUnitsMenu > summary:hover {
  background: var(--hover);
}
/* список узлов — строками: глаз · узел · вписать · позиции сквозь прозрачность;
   окну портал сам ставит display:block */
.assemblyUnitRow {
  display: flex;
  align-items: center;
  gap: 4px;
  margin: 0 0 4px;
}
.assemblyUnitRow:last-child {
  margin-bottom: 0;
}
.assemblyUnitRow > button[data-unit] {
  flex: 1;
  min-width: 0;
}
.assemblyUnitRow > button[data-unit]:first-child {
  margin-left: 32px; /* у «Общего вида» нет глаза — выравниваем по остальным */
}
.assemblyUnitTool {
  flex: none;
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  padding: 0;
}
/* Телефон: строка узла — одна полоса во всю ширину, значки внутри неё справа
   (узел · глаз · вписать · позиции) — без отдельных колонок кнопок. */
@media (max-width: 760px) {
  .assemblyUnitRow {
    gap: 2px;
    padding: 2px 4px 2px 0;
    border: 1px solid #415563;
    border-radius: 7px;
    background: #21313e;
  }
  .assemblyUnitRow:has(> button[data-unit][aria-pressed='true']) {
    background: #315e5d;
    border-color: var(--accent);
  }
  .assemblyUnitRow > button[data-unit] {
    order: 0;
    border: 0;
    background: transparent;
  }
  .assemblyUnitRow > button[data-unit]:first-child {
    margin-left: 0;
  }
  .assemblyUnitRow > [data-tool='eye'] {
    order: 1;
  }
  .assemblyUnitRow > [data-tool='fit'] {
    order: 2;
  }
  .assemblyUnitRow > [data-tool='through'] {
    order: 3;
  }
  .assemblyUnitRow > .assemblyUnitTool {
    width: 32px;
    height: 32px;
    border-color: transparent;
    background-color: transparent;
  }
}
/* скрытый узел — перечёркнутый глаз */
.assemblyUnitTool[data-tool='eye'][data-state='off'] {
  opacity: 0.55;
  background: linear-gradient(
    to top right,
    transparent 46%,
    currentColor 47%,
    currentColor 53%,
    transparent 54%
  );
}
/* «позиции сквозь прозрачность»: как у родителя — приглушено, показывать —
   акцент, скрывать — перечёркнуто */
.assemblyUnitTool[data-tool='through'][data-state='inherit'] {
  opacity: 0.5;
}
.assemblyUnitTool[data-tool='through'][data-state='on'] {
  color: var(--accent);
  border-color: var(--accent);
}
.assemblyUnitTool[data-tool='through'][data-state='off'] {
  background: linear-gradient(to top right, transparent 46%, #ff8a8a 47%, #ff8a8a 53%, transparent 54%);
}
/* Раскрытое меню — в общем верхнем слое (portalToolMenu), выше окон и блоков (П-23);
   без прокрутки вбок (П-8) */
.toolPopupPortal {
  position: fixed !important;
  right: auto !important;
  bottom: auto !important;
  transform: none !important;
  z-index: var(--z-popup) !important;
  box-sizing: border-box;
  overflow-x: hidden !important;
  overflow-y: auto;
}

/* ── Телефон: верх одной строкой, цели 44 px, подписи под значками ── */
#mobileStructure,
#closeStructure {
  display: none;
}
#functionalModules > #mobileStructure {
  display: flex;
}
@media (max-width: 760px) {
  #toolbar.top {
    top: 8px;
    right: 8px;
    gap: 4px;
  }
  #toolbar.top::after {
    display: none; /* место забирает блок выбора — иначе лишний зазор */
  }
  #toolbar #displayPanel {
    flex: 1 1 auto;
    gap: 6px;
    padding: 0;
    background: none;
    border: 0;
  }
  /* кнопки выбора и линейка (П-11): 44 px, на узких телефонах уже (ниже) — строка
     одна на любой ширине */
  #toolbar #selectionTools {
    margin-left: auto;
    gap: 2px;
  }
  #toolbar #selectionTools > *,
  #toolbar #displayPanel .visibilityTools {
    gap: 2px;
  }
  #toolbar #selectionTools button {
    flex: none;
    flex-direction: column;
    gap: 1px;
    width: 44px;
    min-width: 0;
    height: 44px;
    padding: 2px 1px;
    font-size: 0;
    overflow: hidden;
    background: var(--ui-surface);
  }
  #toolbar #selectionTools button::after {
    content: attr(data-label);
    max-width: 100%;
    overflow: hidden;
    font-size: 10px;
    line-height: 12px;
    letter-spacing: -0.2px;
    white-space: nowrap;
  }
  #toolbar #selectionTools #visibilityMode::after {
    content: attr(data-compact-label);
  }
  #viewerMenu #toggleSide,
  #viewerMenuPopup #toggleSide {
    display: none;
  }
  #closeStructure {
    display: block;
    position: absolute;
    right: 10px;
    top: 10px;
    z-index: 2;
    width: 44px;
    height: 44px;
    padding: 0;
    font-size: 24px;
  }
  /* открытый лист поднимает низ сцены: модель, «Фурнитура» и подсказки — над ним */
  html.toolPanelOpen #viewport {
    bottom: var(--sheet-h, 0px);
  }
}
@media (max-width: 400px) {
  #toolbar #selectionTools button {
    width: 40px;
  }
}
@media (max-width: 370px) {
  #toolbar #selectionTools button {
    width: 38px;
  }
  #toolbar #selectionTools button::after {
    content: none;
  }
}
@media (max-width: 340px) {
  #toolbar.top,
  #toolbar #displayPanel {
    gap: 2px;
  }
  #toolbar .viewerMenuToggle {
    width: 36px;
  }
  #toolbar #selectionTools button {
    width: 34px;
  }
}
/* «?» демонстрации в конце строки (guide) — справа, не посередине столбца */
.toolPanelBody :is(.featureRow, .toolStack) > .guideQ {
  align-self: flex-end;
}

/* ── Общие элементы интерфейса (UI-001, часть A). README.md, раздел «Контракт
   элементов»: значок, контейнер, глаз видимости, плавающее окно, фокус. ── */

/* Значок кнопки: <svg class="uiIcon"> или <span class="uiIcon" style="--ui-icon: url(…)">
   (маска, цвет — от текста). Правила «Значки / Подписи» — icon_controls/style.css. */
.uiIcon {
  flex: none;
  width: 18px;
  height: 18px;
}
span.uiIcon {
  display: inline-block;
  background: currentColor;
  mask: var(--ui-icon) center / contain no-repeat;
  -webkit-mask: var(--ui-icon) center / contain no-repeat;
}

/* Контейнер (П-12; ui-rules, п. 2): группа в рамке с названием. Создаёт
   services.toolGroup(row, key, title) / services.displayGroup(key); модуль кладёт в
   тело контейнера свои элементы. Пустой контейнер не виден — места не занимает. */
.toolContainer {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  margin: 0;
  padding: 8px;
  border: 1px solid var(--ui-separator);
  border-radius: 12px;
  background: rgb(255 255 255 / 0.02);
}
.toolContainer:not(:has(> .toolContainerBody > :not([hidden]):not(.hidden))) {
  display: none;
}
.toolContainerTitle {
  margin: 0 2px 2px;
  font-size: 11px;
  font-weight: 600;
  line-height: 14px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ui-text-secondary);
  white-space: nowrap;
}
.toolPanelBody .toolContainerBody.toolStack,
.floatWinBody .toolContainerBody.toolStack {
  gap: 6px;
}
.toolPanelBody .displaySection {
  gap: 8px;
}

/* Видимость — кнопка-глаз (ui-rules, п. 2; П-29), не флажок. Состояние — прежний
   флажок (checked): открытый глаз — видно, перечёркнутый — скрыто. Подпись убираемая,
   значок-состояние виден всегда (он заменяет квадрат флажка). Фокус — на строке.
   <label class="uiEye"><input type="checkbox" id="…" checked>
     <span class="uiIcon uiEyeIcon"></span><span class="uiLabel">Показывать</span></label> */
label.uiEye {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: var(--ui-hit);
  padding: 0 12px;
  border: 1px solid var(--ui-separator);
  border-radius: var(--ui-radius-s);
  background: var(--ui-raised);
  color: var(--ui-text-secondary);
  cursor: pointer;
  user-select: none;
}
label.uiEye > input[type='checkbox'] {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: 0;
  opacity: 0;
  pointer-events: none;
}
label.uiEye > .uiEyeIcon {
  --ui-icon: var(--ui-icon-eye-off);
}
label.uiEye:has(> input:checked) {
  color: var(--ui-text);
}
label.uiEye:has(> input:checked) > .uiEyeIcon {
  --ui-icon: var(--ui-icon-eye);
  color: var(--ui-accent);
}
label.uiEye:has(> input:disabled) {
  opacity: 0.5;
  cursor: default;
}
label.uiEye:hover:not(:has(> input:disabled)) {
  background: var(--hover, #304654);
}
.toolPanelBody :is(.featureRow, .toolStack) > label.uiEye {
  width: 100%;
}
html.uiNoLabels :is(.toolPanelBody, .floatWin) :is(.featureRow, .toolStack) > label.uiEye {
  width: auto;
  align-self: flex-start;
}

/* Плавающее окно (shared/floating_window.js; П-4, П-10): не модальное, тянется за
   заголовок, размер — за правый нижний угол; слой окон 23, окно под рукой — 24.
   На телефоне — правее меню слева до правого края, над нижним листом (Д-76; размер и
   место ставит помощник по --rail-right и --shell-top). */
.floatWin {
  position: fixed;
  z-index: var(--z-window);
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  min-width: 200px;
  min-height: 120px;
  max-width: calc(100vw - 16px);
  max-height: calc(100vh - var(--shell-top) - 8px);
  margin: 0;
  padding: 0;
  overflow: auto;
  resize: both;
  background: var(--ui-surface-solid);
  color: var(--ui-text);
  border: 1px solid var(--ui-separator);
  border-radius: var(--ui-radius-m);
  box-shadow: 0 12px 35px #0008;
  font-size: 13px;
}
.floatWin[hidden],
dialog.floatWin:not([open]) {
  display: none;
}
.floatWin.floatTop {
  z-index: var(--z-window-top);
}
.floatWinHead {
  position: sticky;
  top: 0;
  z-index: 1;
  flex: none;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 8px 4px 14px;
  background: inherit;
  cursor: move;
  user-select: none;
  touch-action: none;
}
.floatWinTitle {
  flex: 0 1 auto;
  min-width: 0;
  margin: 0 auto 0 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
  color: var(--ui-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.floatWinClose {
  flex: none;
  display: grid;
  place-items: center;
  width: var(--ui-hit);
  height: var(--ui-hit);
  padding: 0;
  border-radius: var(--ui-radius-s);
}
.floatWinClose > .uiIcon {
  width: 18px;
  height: 18px;
}
.floatWinBody {
  flex: 1 1 auto;
  min-height: 0;
  padding: 4px 14px 14px;
}
.floatWinBody.toolStack {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
/* строки окна — как строки панели: кнопка, меню, флажок — во всю ширину окна */
.floatWinBody.toolStack > :is(button, label.check) {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: var(--ui-hit);
  padding: 0 12px;
  border: 1px solid var(--ui-separator);
  border-radius: var(--ui-radius-s);
  background: var(--ui-raised);
  color: var(--ui-text);
  font-size: 13px;
  text-align: left;
}
@media (max-width: 760px) {
  .floatWin {
    resize: none;
    max-height: none;
  }
  .floatWinHead {
    cursor: default;
  }
}

/* Видимый фокус с клавиатуры (П-30; ui-rules, п. 5а): рамка 2 px, смещение 2 px. У
   переключателя на скрытом флажке (глаз, строка-флажок) рамка — на строке. */
:is(button, summary, a[href], select, textarea, [role='button'], [role='tab']):focus-visible,
input:not([type='checkbox'], [type='radio'], [type='range']):focus-visible,
:not(label) > input:is([type='checkbox'], [type='radio']):focus-visible {
  outline: 2px solid var(--ui-accent, #9ee2d0) !important;
  outline-offset: 2px !important;
}
input[type='range']:focus-visible {
  outline: 2px solid var(--ui-accent, #9ee2d0) !important;
  outline-offset: 4px !important;
}
label:has(> input:is([type='checkbox'], [type='radio']):focus-visible) {
  outline: 2px solid var(--ui-accent, #9ee2d0) !important;
  outline-offset: 2px !important;
}
label > input:is([type='checkbox'], [type='radio']):focus-visible {
  outline: none !important;
}

