(function(root){'use strict';const ARC_STEP=(3*Math.PI)/180;function makePath(bent,contourLength){const segments=[];for(const s of bent.path||[]){if(s.line){const[x1,y1,x2,y2]=s.line,len=Math.hypot(x2-x1,y2-y1);if(len>1e-9)segments.push({kind:'line',x1,y1,x2,y2,len});}else if(s.arc){const[cx,cy,ax,ay,bx,by]=s.arc,r=Math.hypot(ax-cx,ay-cy),a1=Math.atan2(ay-cy,ax-cx),a2=Math.atan2(by-cy,bx-cx);let d=a2-a1;while(d<=-Math.PI)d+=2*Math.PI;while(d>Math.PI)d-=2*Math.PI;if(r>1e-9)segments.push({kind:'arc',cx,cy,r,a1,d,len:Math.abs(d)*r});}else return null;}
