styles:
/* «Свойства изделия» под названием модели */
.userProps {
  margin: 6px 0 8px;
  font-size: 12px;
}
.userProps summary {
  cursor: pointer;
  color: var(--muted-soft, #9aa9b1);
}
.userProps dl {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 2px 10px;
  margin: 4px 0 0;
}
.userProps dt {
  color: var(--muted-soft, #9aa9b1);
  overflow-wrap: anywhere;
}
.userProps dd {
  margin: 0;
  text-align: right;
  overflow-wrap: anywhere;
