  transform: translateX(-50%);
  width: 440px;
  max-width: calc(100vw - 32px);
  box-sizing: border-box;
  max-height: 70vh;
  overflow: auto;
}
#sectionTools .toolStack {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
#sectionTools #sectionPosition {
  display: block;
  width: 100%;
  min-width: 0;
}

