styles:
#dimensionActions {
  position: fixed;
  z-index: 90;
  width: 220px;
  max-width: calc(100vw - 12px);
  padding: 5px;
  background: var(--panel);
  border: 1px solid var(--popup-border);
  border-radius: 8px;
  box-shadow: 0 12px 35px #0008;
}
#dimensionActions[hidden] {
  display: none;
}
#dimensionActions button {
  display: block;
  width: 100%;
  text-align: left;
  min-height: 40px;
  border: 0;
  background: transparent;
}
#dimensionActions button[hidden] {
  display: none;
}
#dimensionActionValue:not([hidden]) {
  display: flex;
  align-items: center;
  gap: 6px;
}
@media (pointer: coarse) {
  #dimensionActionValue:not([hidden]) {
    min-height: 44px;
  }
}
#dimensionActions button:hover,
#dimensionActions button:focus-visible {
  background: var(--hover);
}
.dimLabel {
  -webkit-touch-callout: none;
  user-select: none;
}
.dimLabel:focus-visible {
  outline: 2px solid #ffb454;
  outline-offset: 3px;
}

