(function(root){'use strict';function install(context,bundle){const{THREE:T,hooks,services,document:doc}=context;if(bundle?.schema!==1)throw new Error('Несовместимый модуль масштаба текстур');const entries=[],byId=new Map(),modes=new Map(),controls=new Map();let disposed=false,unregister=null;const materialId=rec=>{const name=String(rec.material||'').trim();return name?'m:'+name:legacyId(rec);};const legacyId=rec=>(rec.tex?'art:'+rec.tex:'col:'+(rec.color||'#cccccc'));const legacyOf=new Map();const initial=id=>bundle.defaults?.[id]==='fit'||[...(legacyOf.get(id)||[])].some(key=>bundle.defaults?.[key]==='fit')?'fit':'tile';function addEntry(mesh){const uv=mesh.geometry.attributes.uv;if(!uv)return;const source=Float32Array.from(uv.array);let minU=Infinity,minV=Infinity,maxU=-Infinity,maxV=-Infinity;for(let i=0;i<uv.count;i++){minU=Math.min(minU,uv.getX(i));maxU=Math.max(maxU,uv.getX(i));minV=Math.min(minV,uv.getY(i));maxV=Math.max(maxV,uv.getY(i));}
