styles:
.materialCallouts {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 4;
}
.materialCallout {
  position: absolute;
  width: 166px;
  box-sizing: border-box;
  padding: 5px 7px;
  background: #15232de8;
  border: 1px solid #7e9aa5;
  border-radius: 5px;
  color: #eff7fa;
  font: 12px/16px var(--ui-font, system-ui);
  pointer-events: auto; /* щелчок — подсветить все детали материала */
  cursor: pointer;
}
.materialCallout strong,
.materialCallout small {
  display: block;
  white-space: normal;
  overflow-wrap: anywhere;
}
/* артикул — тем же размером, что название, и голубым: читается с первого взгляда */
.materialCallout small {
  font-size: inherit;
  font-weight: 600;
  color: #7ddcff;
}
.materialLeader {
  position: absolute;
  height: 1px;
  background: var(--leader-color, #aec6d0); /* scene_theme: на светлом фоне — тёмная */
  transform-origin: 0 0;
  pointer-events: none;
}
/* Телефон: боковые выноски занимали пол-экрана, поэтому показываем ленту чипов
   снизу — только кружок цвета и артикул. Полное название открывается карточкой. */
.materialChips {
  position: absolute;
  left: 0;
  bottom: var(--hardwareBarH, 8px);
  display: none;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  max-height: 52vh;
  overflow-y: auto;
  overflow-x: hidden;
  z-index: 5;
  pointer-events: auto;
  scrollbar-width: none;
}
.materialChips::-webkit-scrollbar {
  display: none;
}
.materialChips.on {
  display: flex;
}
.materialChip {
  display: flex;
  align-items: center;
  gap: 6px;
  max-width: 93vw;
  padding: 4px 10px 4px 7px;
  border: 1px solid #7e9aa5;
  border-left: 0;
  border-radius: 0 999px 999px 0;
  background: #15232dee;
  color: #eff7fa;
  font: 12px/16px var(--ui-font, system-ui);
  white-space: nowrap;
  cursor: pointer;
  box-shadow: 0 2px 8px #0006;
}
.materialChip .sw {
  width: 11px;
  height: 11px;
  border-radius: 50%;
  flex: none;
  background: #8fa6b1;
}
/* артикул на чипе телефона — как в карточке: голубой и полужирный */
.materialChip .short {
  font-weight: 600;
  color: #7ddcff;
}
.materialChip .full {
  display: none;
  overflow-x: auto;
  scrollbar-width: none;
}
.materialChip .full::-webkit-scrollbar {
  display: none;
}
.materialChip.open {
  border-color: #74d9cf;
  background: #22384a;
}
.materialChip.open .short {
  display: none;
}
.materialChip.open .full {
  display: block;
  max-width: 86vw;
}
.materialChipLeader {
  position: absolute;
  height: 1px;
  background: var(--leader-color, #aec6d0); /* scene_theme: на светлом фоне — тёмная */
  transform-origin: 0 0;
  pointer-events: none;
  display: none;
}

/* Меню «В сносках…»: кнопки «Все/Никого» и прокручиваемый список материалов */
.materialCalloutsBulk {
  display: flex;
  gap: 8px;
  margin-bottom: 6px;
}
.materialCalloutsBulk button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: var(--ui-hit, 32px);
  padding: 3px 10px;
  font-size: 12px;
}
.materialCalloutsBulk button > .uiIcon {
  width: 16px;
  height: 16px;
}
/* без подписей — квадратная кнопка со значком; на телефоне цель касания 44 px */
html.uiNoLabels .materialCalloutsBulk button:has(> .uiIcon) {
  justify-content: center;
  min-width: var(--ui-hit, 32px);
  padding: 0;
}
@media (max-width: 760px) {
  /* только в открытом меню (общий слой): свёрнутое в листе не распирается */
  .toolPopupPortal .materialCalloutsBulk button {
    min-height: 44px;
    min-width: 44px;
  }
}
/* П-21: строки исключённых материалов в «В сносках…» не показываются */
.materialCalloutsBox label[hidden] {
  display: none;
}
.materialCalloutsBox {
  max-height: 58vh;
  overflow: auto;
}
/* ширина — только у открытого меню (общий слой): свёрнутое в листе телефона узкое,
   и список распирал его прокруткой вбок (обход UI-001) */
.toolPopupPortal .materialCalloutsBox {
  min-width: 230px;
}
/* закрытое меню лежит в своём details; на телефоне оно оставалось отрисованным за
   нижним краем (30 px) и содержимое распирало его — пока закрыто, не рисуем */
#materialCalloutsList:not([open]) > .toolPopup {
  display: none;
}

/* выбранный материал: его детали подсвечены (щелчок по выноске или чипу) */
.materialCallout.materialPicked {
  outline: 2px solid #27e6df;
  outline-offset: 1px;
}
.materialChip.materialPicked {
  border-color: #27e6df;
  box-shadow: 0 0 0 1px #27e6df;
}
/* облицованная деталь: слои от лица к тылу; следующие — с «+ » и помельче */
.materialCallout .materialLayer {
  margin-top: 3px;
  font-size: 11px;
  font-weight: 600;
}
.materialCallout .materialPlus {
  color: #8fa2ad;
  font-weight: 700;
}
/* толщина — справа от артикула: «33941 · 18 мм», у облицованной «0,5 / 18 мм» */
.materialCallout .materialMeta small {
  display: inline;
}
.materialCallout .materialThick {
  color: #e9f1f4;
  font-weight: 600;
  white-space: nowrap;
}
.materialCallout .materialMeta small + .materialThick::before {
  content: ' · ';
  color: #8fa2ad;
}
/* дополнения выноски (инструменты редактора материалов): ширину выноски не задают */
.materialCallout .materialCalloutExtra {
  contain: inline-size;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 3px;
  margin-top: 4px;
  cursor: default;
}
/* выноска материала выбранной детали */
.materialCallout.materialSelected {
  outline: 2px solid var(--accent, #6fe3d3);
}

/* Чипы у правого края: слева у меню инструментов не хватило места (RF-013) */
.materialChips.materialChipsRight {
  left: auto;
  right: 0;
  align-items: flex-end;
}
.materialChipsRight .materialChip {
  border-left: 1px solid #7e9aa5;
  border-right: 0;
  border-radius: 999px 0 0 999px;
  padding: 4px 7px 4px 10px;
}
.materialChipsRight .materialChip.open {
  border-left-color: #74d9cf;
}

