styles:
.visibilityTools {
  display: flex;
  gap: 5px;
}
.visibilityTools button[aria-pressed='true'] {
  background: #35615e;
  border-color: #70c7b9;
}
/* Меню: слева столбец пути (RF-037), справа действия. Пункты действий — прямые
   потомки меню (сюда же встают пункты других модулей), путь стоит рядом со всеми
   видимыми пунктами: число строк — --visibility-rows от модуля. */
.visibilityMenu {
  position: fixed;
  z-index: 80;
  display: grid;
  grid-template-columns: auto minmax(220px, auto);
  align-items: start;
  padding: 5px;
  background: var(--panel);
  border: 1px solid var(--popup-border);
  border-radius: 8px;
  box-shadow: 0 12px 35px #0008;
}
.visibilityMenu > :not(.visibilityPath) {
  grid-column: 2;
}
.visibilityMenu button {
  display: block;
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
}
.visibilityMenu button[hidden] {
  display: none;
}
.visibilityMenu button:hover,
.visibilityMenu button:focus-visible {
  background: var(--hover);
}
.visibilityPath {
  grid-column: 1;
  grid-row: 1 / span var(--visibility-rows, 1);
  align-self: stretch;
  display: flex;
  flex-direction: column;
  max-width: 270px;
  margin-right: 5px;
  padding-right: 5px;
  border-right: 1px solid var(--divider);
}
.visibilityMenu .visibilityPathRow {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 5px 10px 5px calc(8px + var(--depth, 0) * 12px);
  font-size: 13px;
  white-space: nowrap;
  color: var(--muted);
}
.visibilityPathName {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.visibilityMenu .visibilityPathRow[aria-current='true'] {
  color: var(--text);
  background: var(--ui-accent-fill, #315e5d);
  box-shadow: inset 2px 0 var(--accent);
}
.visibilityPathUnit {
  flex: none;
  display: inline-flex;
  width: 14px;
  height: 14px;
  color: var(--accent);
}
.visibilityPathUnit > svg {
  width: 14px;
  height: 14px;
}
/* Телефон: путь над действиями, меню не выше 40 % экрана, прокрутка внутри;
   цели касания — 44 px (ui-rules, п. 3) */
@media (max-width: 760px) {
  .visibilityMenu {
    grid-template-columns: minmax(0, 1fr);
    max-width: calc(100vw - 12px);
    max-height: 40vh;
    overflow-y: auto;
    overscroll-behavior: contain;
  }
  .visibilityMenu > :not(.visibilityPath) {
    grid-column: 1;
  }
  .visibilityPath {
    grid-row: auto;
    max-width: none;
    margin: 0 0 5px;
    padding: 0 0 5px;
    border-right: 0;
    border-bottom: 1px solid var(--divider);
  }
}
@media (pointer: coarse), (max-width: 760px) {
  .visibilityMenu button {
    min-height: 44px;
  }
}
.visibilityHidden {
  opacity: 0.46;
}
.assemblyBadge {
  margin-left: 6px;
  padding: 1px 4px;
  border: 1px solid var(--popup-border);
  border-radius: 4px;
  color: var(--accent);
  font-size: 9px;
  white-space: nowrap;
}

