styles:
/* Папки дерева (П-17, П-18): заголовок папки — полужирный, слева полоса своего цвета */
.modelTree .treeFolder > details > summary {
  font-weight: 600;
}
.modelTree .treeFolder {
  border-left: 3px solid var(--treeFolderColor, #6d8aa0);
  margin-left: 2px;
}
.modelTree .treeFolder-layers {
  --treeFolderColor: #c99a3e;
}
.modelTree .treeFolder-layers > details > summary {
  color: #e8c37a;
}
/* слой: метка своего цвета (цвет слоя БАЗИСа из выгрузки, иначе нейтральный) */
.modelTree .treeLayer > details > summary > span:first-of-type::before {
  content: '';
  display: inline-block;
  width: 8px;
  height: 8px;
  margin-right: 6px;
  border-radius: 2px;
  background: var(--treeLayerColor, #8a9aa6);
  vertical-align: 1px;
}
/* глаз слоя — общий label.uiEye (П-29), только размер строки дерева */
.modelTree label.uiEye.treeLayerEye {
  flex: none;
  min-height: 22px;
  height: 22px;
  width: 26px;
  padding: 0;
  justify-content: center;
  border-color: transparent;
  background: transparent;
}
.modelTree label.uiEye.treeLayerEye:hover {
  border-color: #415563;
}
.modelTree label.uiEye.treeLayerEye > .uiLabel:empty {
  display: none;
}
@media (pointer: coarse) {
  .modelTree label.uiEye.treeLayerEye {
    width: 44px;
  }
}

