  padding: 0;
  width: var(--ui-bar);
}
#toolbar #multiSelectToggle > .uiLabel {
  display: none;
}
#toolbar #multiSelectToggle[aria-pressed='true'],
#multiSelectToggle.multiSelectRow[aria-pressed='true'] {
  background: var(--ui-accent-fill);
  border-color: var(--ui-accent);
  color: var(--ui-on-accent);
}
/* телефон: строкой под поиском в листе «Структура» — [значок][подпись] */
#multiSelectToggle.multiSelectRow {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: var(--ui-hit, 44px);
  margin: 8px 0 10px;
  padding: 0 12px;
  border-radius: var(--ui-radius-s, 10px);
  background: var(--ui-raised, #21313e);
  border: 1px solid var(--ui-separator, #415563);
  color: var(--ui-text, inherit);
  text-align: left;
}
/* карточка нескольких: «Выбрано: N» и состав по типам, без полей одной детали */
#selection.multiSelected > :not(#selName, #selKind) {
  display: none !important;
}

