styles:
/* П-40: логотип в правом нижнем углу сцены. Светлый вариант на тёмном фоне, тёмный — при
   «Светлом фоне» (#viewport.sceneLight, модуль scene_theme). Слой ниже панелей и окон.
   Этап 2 (RF-054): знак — кнопка без фона и рамки; в покое непрозрачность 0,25, при
   наведении, фокусе с клавиатуры и пока открыта визитка — 1. Клики в этом месте ловит
   логотип, а не сцена. Общие стили button шаблона сброшены: это знак, не плитка. */
#brandMark {
  position: absolute;
  right: 18px;
  bottom: 16px;
  z-index: 2;
  display: block;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 4px;
  background: none;
  color: inherit;
  font: inherit;
  line-height: 0;
  cursor: pointer;
  opacity: 0.25;
  transition: opacity 0.15s ease;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}
#brandMark:hover,
#brandMark:focus-visible,
#brandMark[aria-expanded='true'] {
  background: none;
  opacity: 1;
}
#brandMark:focus-visible {
  outline: 2px solid #9ee2d0;
  outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
  #brandMark {
    transition: none;
  }
}
#brandMark svg {
  display: block;
  height: 40px;
  width: auto;
  aspect-ratio: 742 / 172;
}
#brandMark .brandMarkLight {
  display: none;
}
#viewport.sceneLight #brandMark .brandMarkDark {
  display: none;
}
#viewport.sceneLight #brandMark .brandMarkLight {
  display: block;
}

/* Визитка владельца: не модальное окно (<dialog>, show()) в общем верхнем слое страницы
   (body, слой раскрытых меню --z-popup), над логотипом, правым краем по его правому краю,
   в границах экрана — место ставит adapter.js. Размер — по рисунку (900 × 500 → 450 × 250),
   без полей: окно — сам рисунок владельца, «×» лежит на его углу. Ширина 450 (половина
   файла): при 360 мелкие строки визитки выходят 5–7 px и не читаются.
   Этап 3: у рисунка свой тёмный фон со скруглением 12 (в окне — 6 px), поэтому у окна нет
   ни своего фона, ни рамки (иначе двойной контур): только тень по тому же скруглению. */
#brandCard {
  position: fixed;
  inset: auto;
  z-index: var(--z-popup, 210);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: none;
  color: #e8e6dd;
  overflow: hidden;
  box-shadow: 0 12px 32px #000a;
}
#brandCard:not([open]) {
  display: none;
}
#brandCard .brandCardArt svg {
  display: block;
  width: 450px;
  max-width: calc(100vw - 20px);
  height: auto;
  aspect-ratio: 900 / 500;
}
/* ссылки: визитка в кривых, поэтому ссылка — прозрачная область <a><rect/></a> поверх
   строки (card.svg). Наведение — лёгкая подсветка области, фокус с клавиатуры — общая
   рамка #9ee2d0 по краю области (обводка не масштабируется вместе с рисунком). */
#brandCard .brandCardArt a {
  cursor: pointer;
  outline: none;
}
#brandCard .brandCardArt a rect {
  transition: fill-opacity 0.15s ease;
}
#brandCard .brandCardArt a:hover rect {
  fill-opacity: 0.08;
}
#brandCard .brandCardArt a:focus-visible rect {
  fill-opacity: 0.08;
  stroke: #9ee2d0;
  stroke-width: 2px;
  vector-effect: non-scaling-stroke;
}
@media (prefers-reduced-motion: reduce) {
  #brandCard .brandCardArt a rect {
    transition: none;
  }
}
#brandCard .brandCardClose {
  position: absolute;
  top: 4px;
  right: 4px;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: none;
  color: #9a9890;
  cursor: pointer;
}
#brandCard .brandCardClose:hover {
  background: #ffffff1a;
  color: #e8e6dd;
}
#brandCard .brandCardClose:focus-visible {
  outline: 2px solid #9ee2d0;
  outline-offset: 2px;
}
#brandCard .brandCardClose svg {
  width: 16px;
  height: 16px;
}

/* телефон: внизу лист и меню — логотип не показывается (умолчание, вопрос владельцу) */
@media (max-width: 760px) {
  #brandMark,
  #brandCard {
    display: none !important;
  }
}
/* печать / PDF страницы — без логотипа и визитки (умолчание, вопрос владельцу) */
@media print {
  #brandMark,
  #brandCard {
    display: none !important;
  }
}

