/* Открывание (RF-051, П-39). Вид кнопок — общий стиль своего места: в верхней строке —
   блок выбора (toolbar/style.css: наведение, выключенная), в листе — кнопки «Отображения».
   Здесь — только то, что общий стиль задаёт по id кнопок «Крепёж» и «Скрыть фасады»:
   нажатое состояние и сжатие подписи в тесной строке — тем же видом. */
#toolbar .openingToggle[aria-pressed='true'] {
  background: var(--ui-accent-fill);
  border-color: var(--ui-accent);
  color: var(--ui-on-accent);
}
#toolbar #selectionTools > #openingDoors {
  order: 3;
}
#toolbar #selectionTools > #openingDrawers {
  order: 3;
}
@media (min-width: 761px) {
  #toolbar.topCompact #selectionTools > .openingToggle {
    font-size: 0;
    padding: 0;
    width: var(--ui-bar);
  }
}
.toolPanelBody .openingToggle[aria-disabled='true'] {
  color: var(--ui-text-tertiary);
}
.openingHint[hidden] {
  display: none;
}

