(function(root){'use strict';const NoColorSpace='',DoubleSide=2,strToU8=text=>new TextEncoder().encode(text);class USDZExporter{async parse(scene,options={}){options=Object.assign({ar:{anchoring:{type:'plane'},planeAnchoring:{alignment:'horizontal'}},quickLookCompatible:false,textureType:'image/png',textureSize:1024},options);const files={};const modelFileName='model.usda';files[modelFileName]=null;let output=buildHeader();output+=buildSceneStart(options);const materials={};const textures={};const extension=options.textureType==='image/jpeg'?'jpg':'png';scene.traverseVisible(object=>{if(object.isMesh){const geometry=object.geometry;const material=object.material;if(material.isMeshStandardMaterial){const doubleSided=material.side===DoubleSide;const geometryName=geometry.id+(doubleSided?'_2':'');const geometryFileName='geometries/Geometry_'+geometryName+'.usda';if(!(geometryFileName in files)){const meshObject=buildMeshObject(geometry,doubleSided);files[geometryFileName]=buildUSDFileAsString(meshObject);}
