{
${array.join('')}
}

`;}
function buildMaterial(material,textures,quickLookCompatible=false,extension='png'){const pad='			';const inputs=[];const samplers=[];function buildTexture(texture,mapType,color){const id=texture.source.id+'_'+texture.flipY;textures[id]=texture;const uv=texture.channel>0?'st'+texture.channel:'st';const WRAPPINGS={1000:'repeat',1001:'clamp',1002:'mirror'};const repeat=texture.repeat.clone();const offset=texture.offset.clone();const rotation=texture.rotation;const xRotationOffset=Math.sin(rotation);const yRotationOffset=Math.cos(rotation);offset.y=1-offset.y-repeat.y;if(quickLookCompatible){offset.x=offset.x/repeat.x;offset.y=offset.y/repeat.y;offset.x+=xRotationOffset/repeat.x;offset.y+=yRotationOffset-1;}else{offset.x+=xRotationOffset*repeat.x;offset.y+=(1-yRotationOffset)*repeat.y;}
