styles:
/* Ходьба (RF-040). Кнопка — общий вид кнопок раздела «Отображение» (toolbar), ползунок —
   общий input[type=range] шаблона: здесь только раскладка и видимость. */
#walkPad[hidden],
#walkHint[hidden] {
  display: none;
}
/* ползунок вне оболочки (страница без toolbar) — отступ от кнопки */
:not(.toolStack) > .walkHeightTool {
  margin-top: 8px;
}
.walkHeightTool output {
  min-width: 52px;
  text-align: right;
}
/* Подсказка: на ПК — клавиши, на телефоне — жесты */
.walkHintTouch {
  display: none;
}
@media (pointer: coarse) {
  .walkHintKeys {
    display: none;
  }
  .walkHintTouch {
    display: inline;
  }
}
/* Кнопки шага и выхода — столбцом справа внизу области просмотра, над лентой
   «Фурнитура» (--hardwareBarH) и под видовым кубом; только на телефоне и в режиме.
   Слева внизу — меню инструментов и «Фурнитура», поэтому справа. */
.walkPad {
  position: absolute;
  z-index: 5;
  right: max(10px, env(safe-area-inset-right));
  bottom: calc(var(--hardwareBarH, 8px) + 16px);
  display: flex;
  flex-direction: column;
  gap: 8px;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}
@media not (pointer: coarse) {
  .walkPad {
    display: none !important;
  }
}
.walkPadButton {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 0;
  border-radius: 22px;
  background: rgba(16, 23, 29, 0.6);
  color: #f2f5f7;
  font: inherit;
  touch-action: none;
  -webkit-touch-callout: none;
}
.walkPadButton[aria-pressed='true'] {
  color: #9ee2d0;
}
.walkPadButton .uiIcon {
  width: 20px;
  height: 20px;
}
.walkPadButton:focus-visible,
.walkToggle:focus-visible {
  outline: 2px solid #9ee2d0;
  outline-offset: 2px;
}

