/* Режим рендера (RF-039). Кнопки, сегменты, флажок и ползунки — общий вид оболочки
   (toolbar/style.css, общий input[type=range] шаблона); здесь только то, чего у неё нет. */
/* скрытое — по id: общее правило столбца (.toolStack) задаёт display сильнее, чем [hidden] */
#renderModeOptions[hidden],
#renderModeStatus[hidden] {
  display: none;
}
/* выбор цвета фона — родной диалог браузера; само поле не занимает места */
.renderModeColor {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  border: 0;
  opacity: 0;
  pointer-events: none;
}
.renderModeRange .renderModeRangeLabel {
  width: auto;
  text-align: left;
}
.renderModeRange output {
  min-width: 38px;
  text-align: right;
}
/* холст WebGPU (уровень GI) — поверх холста техвида, тех же размеров; события мыши
   проходят к холсту техвида (вращение, выбор) */
.renderGpuCanvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
/* пока режим включён — без подписей размеров и точек замера поверх картинки */
#viewport.renderModeOn #labels,
#viewport.renderModeOn #snap,
#viewport.renderModeOn #snapHint {
  visibility: hidden !important;
}

