styles:
/* Статистика нажатий и предложения: блок в «Ещё», кнопка в строке подсказок, окно */
.usageTools {
  display: grid;
  gap: 4px;
  margin-top: 8px;
}
.usageTools .usageHint {
  color: var(--muted, #8fa2ad);
  font-size: 11px;
  line-height: 1.35;
}
.usagePill {
  pointer-events: auto;
  border: 0;
  cursor: pointer;
  color: #ffd970;
}
.usagePill:hover {
  background: #263744;
}
.usageDialog {
  max-width: 440px;
  width: calc(100vw - 32px);
  box-sizing: border-box;
  border: 1px solid #6c8696;
  border-radius: 8px;
  background: #101a21;
  color: #e9f1f4;
  padding: 16px 18px;
}
.usageDialog::backdrop {
  background: #03080c99;
}
.usageDialog h3 {
  margin: 0 0 6px;
}
.usageDialog p {
  margin: 0 0 8px;
  font-size: 13px;
  line-height: 1.4;
}
.usageField {
  display: grid;
  gap: 3px;
  margin-bottom: 8px;
  font-size: 13px;
}
.usageField input,
.usageField textarea {
  width: 100%;
  box-sizing: border-box;
}
.usageStatus:empty {
  display: none;
}
.usageButtons {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}
.usagePrimary {
  background: #315e5d;
  border-color: var(--accent, #6fe3d3);
}
/* Строка о статистике для клиента: по центру над нижней строкой подсказок (и над
   кнопкой фурнитуры на телефоне), исчезает сама */
.usageNotice {
  position: fixed;
  left: 16px;
  right: 16px;
  bottom: 76px;
  margin: 0 auto;
  width: max-content;
  z-index: 60;
  display: flex;
  align-items: center;
  gap: 10px;
  max-width: calc(100vw - 32px);
  box-sizing: border-box;
  padding: 7px 8px 7px 14px;
  border: 1px solid #415563;
  border-radius: 10px;
  background: #17232df2;
  color: #e9f1f4;
  font-size: 13px;
  line-height: 1.35;
  box-shadow: 0 4px 16px #0008;
  cursor: pointer;
}
.usageNotice[hidden] {
  display: none;
}
.usageNotice button {
  flex: none;
  min-width: 32px;
  min-height: 32px;
  border: 0;
  background: none;
  color: inherit;
  font-size: 18px;
  cursor: pointer;
}
/* значок лампы вместо эмодзи (ui-rules, п. 5а): рисунок цвета текста кнопки */
.usageFeedback,
.usagePill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.usageFeedback .uiIcon,
.usagePill .uiIcon {
  flex: none;
  width: 16px;
  height: 16px;
}

