styles:
/* Кнопка «Демонстрация»: в верхней строке перед языком */
.guideOpen {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}
.guideOpen svg {
  width: 17px;
  height: 17px;
  flex: none;
}
/* Телефон: в области модели, слева от значков проекции (projection: top 10,
   right 10, ширина 68) — под кнопкой «Обновить» верхней строки */
.guideOpen.guideOpenFloating {
  position: absolute;
  top: 10px;
  right: 86px;
  z-index: 6;
  width: 34px;
  height: 34px;
  padding: 0;
  justify-content: center;
  background: #17232de8;
}
/* Телефон с меню слева: сразу под меню, у его левого края (владелец 03.11.2026). Место —
   от низа меню (--guide-top, --guide-left ставит adapter.js по меню и области модели);
   под слоем выносок заметок (z-index 4): заметку «?» не закрывает */
.guideOpen.guideOpenFloating.guideUnderRail {
  top: var(--guide-top);
  left: var(--guide-left);
  right: auto;
  z-index: 3;
}
.guideOpen.guideOpenFloating.guideNoRoom {
  visibility: hidden;
}
.guideOpenFloating .guideOpenLabel {
  display: none;
}
/* Значок «?» в конце ряда: справка по кнопкам этого ряда. На телефоне не
   показываем — строки тесные, справка там через «Демонстрацию». */
.guideQ {
  display: inline-grid;
  place-items: center;
  box-sizing: border-box;
  width: 18px;
  height: 18px;
  min-width: 18px;
  padding: 0;
  margin: 0 0 0 4px;
  border-radius: 50%;
  border: 1px solid #5b7383;
  background: #1b2a35;
  color: #a9c3cf;
  font: 700 11px/16px var(--ui-font, system-ui, sans-serif);
  cursor: pointer;
  align-self: center;
  vertical-align: middle;
  position: relative;
  top: -1px;
  flex: none;
}
/* значок — рисунок «?» общего набора: свой круг у него уже есть */
.guideQ:has(> svg) {
  width: 20px;
  height: 20px;
  min-width: 20px;
  border-color: transparent;
  background: none;
}
.guideQ > svg {
  width: 18px;
  height: 18px;
}
.guideQ:hover,
.guideQ:focus-visible {
  border-color: var(--accent, #6fe3d3);
  color: #fff;
}
@media (max-width: 700px) {
  .guideQ {
    display: none !important;
  }
}
/* Слой шага: затемнение с вырезами, рамки элементов, выноски, поля описаний */
.guideLayer {
  position: fixed;
  inset: 0;
  z-index: 250;
}
.guideLayer[hidden] {
  display: none;
}
.guideShade {
  position: absolute;
  inset: 0;
}
.guideDim {
  fill: #03080cb8;
}
.guideFrame {
  fill: none;
  stroke: #fff;
  stroke-width: 2;
}
.guideLine {
  fill: none;
  stroke: #fff;
  stroke-width: 4;
  stroke-linejoin: miter;
}
.guideDot {
  fill: #fff;
}
.guideCallout {
  position: absolute;
  box-sizing: border-box;
  padding: 9px 12px;
  border: 2.5px solid #fff;
  border-radius: 6px;
  background: #0b1217f5;
  color: #e9f1f4;
  font-size: 13px;
  line-height: 1.38;
  display: grid;
  gap: 3px;
  box-shadow: 0 8px 22px #000a;
}
.guideCallout strong,
.guideOffer strong {
  color: #fff;
  font-size: 14px;
}
.guideBar {
  position: absolute;
  left: 50%;
  bottom: 14px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: calc(100% - 20px);
  box-sizing: border-box;
  padding: 8px 10px;
  border: 1px solid #6c8696;
  border-radius: 8px;
  background: #101a21f7;
  color: #e9f1f4;
  box-shadow: 0 8px 22px #000b;
}
.guideBar strong {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.guideCounter {
  color: #9fb4bf;
  font-size: 12px;
  white-space: nowrap;
}
.guidePrimary {
  background: #315e5d;
  border-color: var(--accent, #6fe3d3);
}
.guideIntro {
  max-width: 420px;
  border: 2px solid #fff;
  border-radius: 8px;
  background: #101a21;
  color: #e9f1f4;
  padding: 16px 18px;
}
.guideIntro::backdrop {
  background: #03080c99;
}
.guideIntro h3 {
  margin: 0 0 8px;
}
.guideIntro p {
  margin: 0 0 8px;
  line-height: 1.4;
  font-size: 13.5px;
}
.guideIntro select {
  width: 100%;
  margin: 6px 0 12px;
}
.guideIntroButtons {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}
.guideOffer {
  position: fixed;
  z-index: 240;
  width: 250px;
  box-sizing: border-box;
  padding: 11px 13px;
  border: 2.5px solid #fff;
  border-radius: 7px;
  background: #0b1217f7;
  color: #e9f1f4;
  display: grid;
  gap: 6px;
  font-size: 13px;
  box-shadow: 0 8px 22px #000b;
}
.guideOffer[hidden] {
  display: none;
}
@media (max-width: 700px) {
  .guideBar {
    bottom: 8px;
    gap: 6px;
    padding: 6px 8px;
    font-size: 12px;
  }
  .guideCallout {
    font-size: 12px;
    padding: 7px 9px;
  }
}

