styles:
/* Кнопка списка клавиш — справа в верхней строке; на сенсорном экране клавиш нет */
.hotkeysMenu > summary {
  display: grid;
  place-items: center;
  width: var(--ui-bar, 34px);
  height: var(--ui-bar, 34px);
  padding: 0;
  list-style: none;
  border: 1px solid var(--ui-separator, #31414b);
  border-radius: var(--ui-radius-s, 10px);
  background: var(--ui-surface, #17232df2);
  color: var(--ui-text, #e8eef0);
}
.hotkeysMenu > summary::-webkit-details-marker {
  display: none;
}
.hotkeysMenu[open] > summary {
  background: var(--ui-accent-fill, #315e5d);
  border-color: var(--ui-accent, #9ee2d0);
}
.hotkeysMenu svg {
  width: 20px;
  height: 20px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}
@media (max-width: 760px), (pointer: coarse) and (hover: none) {
  #hotkeysMenu {
    display: none;
  }
}
.hotkeysList {
  width: 320px;
}
.hotkeysList h3 {
  margin: 0 0 8px;
  font-size: 15px;
}
.hotkeysList dl {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 8px 12px;
  align-items: center;
  margin: 0 0 8px;
  font-size: 13px;
}
.hotkeysList dt {
  white-space: nowrap;
}
.hotkeysList dd {
  margin: 0;
}
.hotkeysList kbd,
.toolRail > button[data-hotkey]::after {
  /* шрифт интерфейса (RF-055) вместо моноширинного: прописные Inter крупнее и шире
     знаков Consolas — 10 px и поля 4 px держат прежнюю ширину столбца клавиш */
  font: 10px/16px var(--ui-font, system-ui);
  font-variant-numeric: tabular-nums;
  color: var(--ui-text, #e8eef0);
  background: var(--ui-raised, #21313e);
  border: 1px solid var(--ui-separator, #31414b);
  border-bottom-width: 2px;
  border-radius: 5px;
  padding: 0 4px;
}
/* цифра в углу кнопки меню слева — только при мыши */
.toolRail > button[data-hotkey]::after {
  content: attr(data-hotkey);
  position: absolute;
  top: 4px;
  right: 4px;
  padding: 0 3px;
  font-size: 10px;
  line-height: 13px;
  border-bottom-width: 1px;
  color: var(--ui-text-tertiary, #7f97a5);
  background: transparent;
}
@media (max-width: 760px), (pointer: coarse) and (hover: none) {
  .toolRail > button[data-hotkey]::after {
    content: none;
  }
}

